text = unicodedata.normalize("NFKD", title)
text = text.encode("ascii", "ignore").decode("ascii").lower()
text = text.replace("'", "")  # Remove apostrophes without leaving a gap
slug = _NON_ALNUM.sub("-", text).strip("-")
if not slug:
    raise ValueError(f"cannot build a slug from {title!r}")
if len(slug) > max_length:
    # Truncate on word boundary
    words = slug.split("-")
    result = words[0]
    if len(result) > max_length:
        # First word alone is longer than max_length
        result = result[:max_length]
    else:
        for word in words[1:]:
            candidate = result + "-" + word
            if len(candidate) <= max_length:
                result = candidate
            else:
                break
    slug = result
return slug
